package com.proofclean.config;
import com.proofclean.user.service.UserService;import jakarta.servlet.*;import jakarta.servlet.http.*;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component @RequiredArgsConstructor
public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtTokenProvider jwtTokenProvider; private final UserService userService; @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain) throws ServletException, IOException { String header=request.getHeader("Authorization"); if(header!=null&&header.startsWith("Bearer ")){String token=header.substring(7); if(jwtTokenProvider.validate(token)){var user=userService.getByEmail(jwtTokenProvider.getSubject(token)); var auth=new UsernamePasswordAuthenticationToken(user.getEmail(), null, List.of(new SimpleGrantedAuthority("ROLE_"+user.getRole().name()))); SecurityContextHolder.getContext().setAuthentication(auth);}} chain.doFilter(request,response);} }
